<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyAcceptanceFenceFixture.php';
use DigiForge\POD\PrintifyAcceptanceSafetyGeneration as Generation;
final class PrintifyAcceptanceSafetyGenerationTest extends WP_UnitTestCase {
 private array $settings=[];
 public function set_up():void {parent::set_up();global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$this->settings=$wpdb->get_results('SELECT * FROM '.\DigiForge\Database\Tables::settings(),ARRAY_A);\DigiForge\Core\Settings::protectProduction();$wpdb->delete($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1']);$wpdb->delete($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1_quarantined']);}
 public function tear_down():void {global $wpdb;\DigiForge\Security\Logger::write('printify_acceptance_generation_fixture_cleanup');$wpdb->delete($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1']);$wpdb->delete($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1_quarantined']);$wpdb->query('DELETE FROM '.\DigiForge\Database\Tables::settings());foreach($this->settings as $row)$wpdb->insert(\DigiForge\Database\Tables::settings(),$row);parent::tear_down();}
 private function next():string {self::assertTrue(class_exists(Generation::class),'Durable acceptance revocation generation required');$r=Generation::terminate();self::assertNotWPError($r);return $r;}
 public function testMissingGenerationDeniesWithoutCreatingState():void {self::assertTrue(class_exists(Generation::class));self::assertWPError(Generation::current());self::assertFalse(get_option('df_acceptance_safety_generation_v1',false));}
 public function testEveryTerminationChangesGenerationAndRejectsStaleSession():void {$a=$this->next();self::assertTrue(Generation::check($a)===true);$b=$this->next();self::assertNotSame($a,$b);self::assertWPError(Generation::check($a));self::assertTrue(Generation::check($b)===true);}
 public function testRepeatedExplicitEmergencyEventRotatesWhileStopAllIsTrue():void {$a=$this->next();self::assertTrue(\DigiForge\Core\Settings::get('stop_all',true));$b=$this->next();self::assertWPError(Generation::check($a));$this->next();self::assertWPError(Generation::check($b));}
 public function testTamperedStateFailsClosed():void {$a=$this->next();global $wpdb;$wpdb->update($wpdb->options,['option_value'=>'{}'],['option_name'=>'df_acceptance_safety_generation_v1']);self::assertWPError(Generation::check($a));}
 public function testMissingAuditAnchorDenies():void {$a=$this->next();global $wpdb;$wpdb->delete(\DigiForge\Database\Tables::audit_log(),['event_type'=>'printify_acceptance_emergency_generation','object_id'=>$a]);self::assertWPError(Generation::check($a));}
 public function testOuterTransactionTerminationIsRejectedNotAcknowledged():void {$a=$this->next();global $wpdb;$wpdb->query('START TRANSACTION');try{self::assertWPError(Generation::terminate());self::assertWPError(Generation::check($a));}finally{$wpdb->query('ROLLBACK');}self::assertWPError(Generation::check($a),'A rolled-back database must not restore authority after the independent fence changes');}
 public function testExplicitEmergencyEventCannotEnableBusinessOperations():void {$a=$this->next();$this->next();self::assertWPError(Generation::check($a));self::assertFalse(\DigiForge\Core\Settings::is_enabled('printify'));self::assertTrue(\DigiForge\Core\Settings::safety_locked());}
 public function testRejectedTerminationNeverCommitsCallerTransaction():void {$this->next();global $wpdb;$wpdb->query('START TRANSACTION');try{self::assertWPError(Generation::terminate());self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));}finally{$wpdb->query('ROLLBACK');}}
 public function testConcurrentCompareExchangeLoserCannotOverwriteNewEvent():void {
  $old=$this->next();global $wpdb;$primary=$wpdb;$secondary=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$secondary->set_prefix($primary->prefix);$winner=null;$entered=false;$filter=static function(string $sql)use(&$entered,&$winner,$primary,$secondary):string{if(!$entered&&str_starts_with($sql,'UPDATE '.$primary->options.' SET option_value=')&&str_contains($sql,'df_acceptance_safety_generation_v1')){$entered=true;$GLOBALS['wpdb']=$secondary;try{$winner=Generation::terminate();}finally{$GLOBALS['wpdb']=$primary;}}return $sql;};add_filter('query',$filter);try{$loser=Generation::terminate();}finally{remove_filter('query',$filter);$secondary->close();}self::assertWPError($winner);self::assertSame('FENCED_DRAIN_PENDING',$winner->get_error_data()['revocation_state']);self::assertWPError($loser);self::assertWPError(Generation::current());self::assertWPError(Generation::check($old));$fresh=$this->next();self::assertTrue(Generation::check($fresh)===true);
 }
 public function testAuditFailureAfterGenerationChangeDeniesOldAndNewEvidence():void {
  $old=$this->next();$table=\DigiForge\Database\Tables::audit_log();$filter=static fn(string $sql):string=>str_starts_with($sql,'INSERT INTO `'.$table.'`')&&str_contains($sql,'printify_acceptance_emergency_generation')?'INSERT INTO nonexistent_acceptance_audit_table VALUES (1)':$sql;add_filter('query',$filter);global $wpdb;$previous=$wpdb->suppress_errors(true);try{self::assertWPError(Generation::terminate());}finally{remove_filter('query',$filter);$wpdb->suppress_errors($previous);}self::assertWPError(Generation::check($old));self::assertWPError(Generation::current());
 }
 public function testFailedDatabaseWriteCannotResurrectPreviousGeneration():void {
  $old=$this->next();$filter=static fn(string $sql):string=>str_starts_with($sql,'UPDATE ')&&str_contains($sql,'df_acceptance_safety_generation_v1')?'UPDATE nonexistent_generation_sink SET value=1':$sql;add_filter('query',$filter);global $wpdb;$previous=$wpdb->suppress_errors(true);try{self::assertWPError(Generation::terminate());}finally{remove_filter('query',$filter);$wpdb->suppress_errors($previous);}self::assertWPError(Generation::check($old));self::assertWPError(Generation::current());
 }
 public function testFenceFailureQuarantineSurvivesCallerRollbackAndPermissionRecovery():void {
  $old=$this->next();global $wpdb;$wpdb->query('START TRANSACTION');chmod(DIGIFORGE_PRINTIFY_ACCEPTANCE_FENCE_DIR.'/events',0400);try{self::assertWPError(Generation::terminate());self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));}finally{chmod(DIGIFORGE_PRINTIFY_ACCEPTANCE_FENCE_DIR.'/events',0600);$wpdb->query('ROLLBACK');}self::assertWPError(Generation::check($old));self::assertWPError(Generation::terminate());self::assertSame('DENIED_UNTIL_SEPARATE_HOST_RECOVERY',$wpdb->get_var($wpdb->prepare('SELECT option_value FROM '.$wpdb->options.' WHERE option_name=%s','df_acceptance_safety_generation_v1_quarantined')));
 }
 public function testBothPersistenceChannelsUnavailableReportsHostFailStopWithoutFalseRevocationClaim():void {
  $old=$this->next();global $wpdb;$wpdb->query('START TRANSACTION');$wpdb->insert($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1_quarantined','option_value'=>'UNCOMMITTED_FIXTURE','autoload'=>'off']);chmod(DIGIFORGE_PRINTIFY_ACCEPTANCE_FENCE_DIR.'/events',0400);$start=microtime(true);try{$r=Generation::terminate();self::assertWPError($r);self::assertSame('HOST_FAIL_STOP_REQUIRED',$r->get_error_data()['revocation_state']);self::assertFalse($r->get_error_data()['durable_revocation_recorded']);self::assertLessThan(4.0,microtime(true)-$start);self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));}finally{chmod(DIGIFORGE_PRINTIFY_ACCEPTANCE_FENCE_DIR.'/events',0600);$wpdb->query('ROLLBACK');}
  self::assertTrue(Generation::check($old)===true,'Explicit fault boundary: neither store persisted evidence, so revocation cannot be claimed');self::assertFalse(\DigiForge\POD\PrintifyAcceptancePolicy::decision('GET',true,true)['runtime_execution_authorized']);
 }
}
